<?php
require_once __DIR__.'/legacy_review_schema.php';
/** Optional working copy of Legacy finance. Only the CLI installer performs DDL. */
function lop_ready(mysqli $db,bool $refresh=false): bool {
    static $cache=[];$key=spl_object_id($db).':'.$db->thread_id;if(!$refresh&&array_key_exists($key,$cache))return $cache[$key];
    return $cache[$key]=(int)$db->query("SELECT COUNT(*) FROM information_schema.VIEWS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('legacy_op_groups','legacy_op_owners','legacy_op_payments','legacy_op_journals','legacy_op_accounts','legacy_op_tariffs','legacy_op_pending','legacy_op_obligations','legacy_op_audit')")->fetch_row()[0]===9
        && lop_review_schema_ready($db)
        && (int)$db->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='master_kelas' AND COLUMN_NAME IN ('jenis','nama_custom')")->fetch_row()[0]===2
        && (int)$db->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME IN ('lop_audit_update','lop_audit_delete','lop_id_payments','lop_id_journals')")->fetch_row()[0]===4;
}
function lop_schema_apply(mysqli $db): void {
    if(PHP_SAPI!=='cli')throw new LogicException('Pemasangan melalui CLI.');
    require_once __DIR__.'/legacy_full_schema.php';legacy_full_schema_apply($db);
    foreach(['master_kelas_data','siswa_data','tagihan_biaya_lain_data'] as $table){$indices=$db->query("SELECT INDEX_NAME,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='$table' AND NON_UNIQUE=0 GROUP BY INDEX_NAME")->fetch_all(MYSQLI_ASSOC);if(!in_array('unit_id,id',array_column($indices,'cols'),true))$db->query("ALTER TABLE $table ADD UNIQUE KEY lop_unit_identity(unit_id,id)");}
    $defs=[
        'groups'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,code VARCHAR(100) NOT NULL,label VARCHAR(150) NOT NULL,kind VARCHAR(20) NOT NULL,aliases JSON NOT NULL,master_kelas_id INT NULL,UNIQUE KEY(unit_id,code),UNIQUE KEY(unit_id,id),FOREIGN KEY(unit_id,master_kelas_id) REFERENCES master_kelas_data(unit_id,id),CHECK(kind IN ('academic','psb','out','alumni','account','legacy'))",
        'owners'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,batch_id CHAR(32) NOT NULL,source_identity VARCHAR(255) NOT NULL,name VARCHAR(255) NOT NULL,kind VARCHAR(20) NOT NULL,group_id BIGINT NULL,student_id INT NULL,entry_year VARCHAR(9) NULL,source_class VARCHAR(100) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'ready',UNIQUE KEY(unit_id,batch_id,source_identity),UNIQUE KEY(unit_id,student_id),UNIQUE KEY(unit_id,id),FOREIGN KEY(unit_id,batch_id) REFERENCES legacy_full_batches_data(unit_id,id),FOREIGN KEY(unit_id,group_id) REFERENCES legacy_op_groups_data(unit_id,id),FOREIGN KEY(unit_id,student_id) REFERENCES siswa_data(unit_id,id),CHECK(kind IN ('active','psb','out','alumni','account','legacy')),CHECK(state IN ('ready','held'))",
        'accounts'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,owner_id BIGINT NOT NULL,source_balance DECIMAL(15,2) NOT NULL,opening DECIMAL(15,2) NOT NULL,balance DECIMAL(15,2) NOT NULL,version INT NOT NULL DEFAULT 1,effective_date DATE NOT NULL,UNIQUE KEY(unit_id,owner_id),UNIQUE KEY(unit_id,id),FOREIGN KEY(unit_id,owner_id) REFERENCES legacy_op_owners_data(unit_id,id),CHECK(opening>=0),CHECK(balance>=0)",
        'payments'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,batch_id CHAR(32) NOT NULL,owner_id BIGINT NOT NULL,row_key CHAR(64) NOT NULL,source_table VARCHAR(64) NOT NULL,source_operator VARCHAR(255) NULL,source_date DATETIME NULL,source_period VARCHAR(100) NOT NULL,class_snapshot VARCHAR(100) NOT NULL,method VARCHAR(100) NULL,note VARCHAR(1000) NOT NULL DEFAULT '',items JSON NOT NULL,total DECIMAL(15,2) NOT NULL,version INT NOT NULL DEFAULT 1,cancelled TINYINT NOT NULL DEFAULT 0,UNIQUE KEY(unit_id,batch_id,row_key),UNIQUE KEY(unit_id,id),KEY(unit_id,source_date,owner_id),FOREIGN KEY(unit_id,batch_id) REFERENCES legacy_full_batches_data(unit_id,id),FOREIGN KEY(unit_id,owner_id) REFERENCES legacy_op_owners_data(unit_id,id),CHECK(total>=0),CHECK(cancelled IN (0,1))",
        'journals'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,batch_id CHAR(32) NOT NULL,owner_id BIGINT NOT NULL,row_key CHAR(64) NOT NULL,source_operator VARCHAR(255) NULL,source_date DATETIME NOT NULL,incoming DECIMAL(15,2) NOT NULL,outgoing DECIMAL(15,2) NOT NULL,origin VARCHAR(10) NOT NULL DEFAULT 'legacy',note VARCHAR(1000) NOT NULL DEFAULT '',version INT NOT NULL DEFAULT 1,cancelled TINYINT NOT NULL DEFAULT 0,UNIQUE KEY(unit_id,batch_id,row_key),UNIQUE KEY(unit_id,id),KEY(unit_id,owner_id,source_date),FOREIGN KEY(unit_id,batch_id) REFERENCES legacy_full_batches_data(unit_id,id),FOREIGN KEY(unit_id,owner_id) REFERENCES legacy_op_owners_data(unit_id,id),CHECK((incoming>0 AND outgoing=0) OR (incoming=0 AND outgoing>0)),CHECK(origin IN ('legacy','new')),CHECK(cancelled IN (0,1))",
        'tariffs'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,student_id INT NOT NULL,owner_id BIGINT NOT NULL,amount DECIMAL(15,2) NOT NULL,source_amount DECIMAL(15,2) NOT NULL,basis VARCHAR(10) NOT NULL DEFAULT 'legacy',version INT NOT NULL DEFAULT 1,UNIQUE KEY(unit_id,student_id),FOREIGN KEY(unit_id,student_id) REFERENCES siswa_data(unit_id,id),FOREIGN KEY(unit_id,owner_id) REFERENCES legacy_op_owners_data(unit_id,id),CHECK(amount>=0),CHECK(basis IN ('legacy','master'))",
        'pending'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,batch_id CHAR(32) NOT NULL,source_identity VARCHAR(255) NOT NULL,row_key CHAR(64) NOT NULL,section VARCHAR(30) NOT NULL,code VARCHAR(60) NOT NULL,message VARCHAR(1000) NOT NULL,payload JSON NOT NULL,version INT NOT NULL DEFAULT 1,resolved TINYINT NOT NULL DEFAULT 0,UNIQUE KEY(unit_id,batch_id,row_key,section),KEY(unit_id,batch_id,resolved),FOREIGN KEY(unit_id,batch_id) REFERENCES legacy_full_batches_data(unit_id,id)",
        'obligations'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,owner_id BIGINT NOT NULL,category VARCHAR(80) NOT NULL,period VARCHAR(20) NOT NULL,principal DECIMAL(15,2) NOT NULL,remaining DECIMAL(15,2) NOT NULL,evidence VARCHAR(1000) NOT NULL,bill_id BIGINT NULL,version INT NOT NULL DEFAULT 1,UNIQUE KEY(unit_id,owner_id,category,period),UNIQUE KEY(unit_id,id),FOREIGN KEY(unit_id,owner_id) REFERENCES legacy_op_owners_data(unit_id,id),FOREIGN KEY(unit_id,bill_id) REFERENCES tagihan_biaya_lain_data(unit_id,id),CHECK(principal>=0),CHECK(remaining>=0)",
        'audit'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,actor_id INT NOT NULL,entity_type VARCHAR(30) NOT NULL,entity_id BIGINT NOT NULL,request_key CHAR(64) NOT NULL,reason VARCHAR(1000) NOT NULL,before_data JSON NOT NULL,after_data JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(unit_id,request_key),FOREIGN KEY(actor_id) REFERENCES admin(id)"
    ];
    foreach($defs as $name=>$ddl){$table='legacy_op_'.$name;$db->query("CREATE TABLE IF NOT EXISTS {$table}_data ($ddl) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci");$db->query("CREATE OR REPLACE VIEW $table AS SELECT * FROM {$table}_data WHERE current_unit_id()=0 OR unit_id=current_unit_id() WITH CASCADED CHECK OPTION");}
    foreach(['UPDATE','DELETE'] as $event){$trigger='lop_audit_'.strtolower($event);if(!(int)$db->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='$trigger'")->fetch_row()[0])$db->query("CREATE TRIGGER $trigger BEFORE $event ON legacy_op_audit_data FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Audit migrasi tidak dapat diubah'");}
    foreach(['payments','journals'] as $kind){$name='lop_id_'.$kind;if(!(int)$db->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='$name'")->fetch_row()[0])$db->query("CREATE TRIGGER $name AFTER INSERT ON legacy_op_{$kind}_data FOR EACH ROW BEGIN IF NEW.id>=1000000000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batas identitas transaksi migrasi tercapai'; END IF; END");}
    lop_review_schema_apply($db);
    require_once __DIR__.'/special_classes_schema.php';special_classes_schema_apply($db);
    if(!lop_ready($db,true))throw new RuntimeException('Pemasangan skema operasional belum lengkap.');
}
